// Copies the TradingView Lightweight Charts standalone build into a TS module
// so the chart WebView works offline and never loads remote code.
const fs = require('fs');
const path = require('path');

const src = path.join(path.dirname(require.resolve('lightweight-charts/package.json')), 'dist', 'lightweight-charts.standalone.production.js');
const out = path.join(__dirname, '..', 'src', 'generated', 'lightweightCharts.ts');
const code = fs.readFileSync(src, 'utf8');
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(
  out,
  '// AUTO-GENERATED by scripts/bundle-chart-lib.js. Do not edit.\n' +
    '// TradingView Lightweight Charts (Apache-2.0). https://www.tradingview.com/lightweight-charts/\n' +
    `export const LIGHTWEIGHT_CHARTS_JS: string = ${JSON.stringify(code)};\n`
);
console.log('Bundled lightweight-charts into', path.relative(process.cwd(), out));
